import math

class Solution:
    def twoEggDrop(self, n: int) -> int:
        return math.ceil((-1 + math.sqrt(1 + 8 * n)) / 2)

class Solution {
public:
    int twoEggDrop(int n) {
        return ceil((-1.0 + sqrt(1.0 + 8.0 * n)) / 2.0);
    }
};

class Solution {
    public int twoEggDrop(int n) {
        return (int)Math.ceil((-1.0 + Math.sqrt(1.0 + 8.0 * n)) / 2.0);
    }
}

/**
 * @param {number} n
 * @return {number}
 */
var twoEggDrop = function(n) {
    return Math.ceil((-1 + Math.sqrt(1 + 8 * n)) / 2);
};
